import*as z from"zod/v4";import{InvalidRequestError,InvalidClientError,ServerError,OAuthError}from"../errors.js";const ClientAuthenticatedRequestSchema=z.object({client_id:z.string(),client_secret:z.string().optional()});export function authenticateClient({clientsStore:e}){return async(t,r,n)=>{try{const r=ClientAuthenticatedRequestSchema.safeParse(t.body);if(!r.success)throw new InvalidRequestError(String(r.error));const{client_id:i,client_secret:o}=r.data,s=await e.getClient(i);if(!s)throw new InvalidClientError("Invalid client_id");if(s.client_secret){if(!o)throw new InvalidClientError("Client secret is required");if(s.client_secret!==o)throw new InvalidClientError("Invalid client_secret");if(s.client_secret_expires_at&&s.client_secret_expires_at<Math.floor(Date.now()/1e3))throw new InvalidClientError("Client secret has expired")}t.client=s,n()}catch(e){if(e instanceof OAuthError){const t=e instanceof ServerError?500:400;r.status(t).json(e.toResponseObject())}else{const e=new ServerError("Internal Server Error");r.status(500).json(e.toResponseObject())}}}}